import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  LinearProgress,
  List,
  ListItem,
  ListItemText,
  Stack,
  Typography,
} from '@mui/material';
import ArrowForwardIcon from '@mui/icons-material/ArrowForward';
import { Link as RouterLink } from 'react-router-dom';
import ApiService from '../../services/api';

interface ChecklistItem {
  id?: string;
  title?: string;
  description?: string;
  status?: string;
}

interface GapChecklist {
  overallReadinessScore?: number;
  scopeNote?: string;
  sections?: Record<string, { section?: string; readinessScore?: number; items?: ChecklistItem[] }>;
  openGaps?: Array<{ title?: string; description?: string }>;
  priorityActions?: Array<{
    action?: string;
    detail?: string;
    priority?: string;
    hubLink?: string;
    actionLabel?: string;
    gapId?: string;
  }>;
  fullComplianceBlockers?: string[];
}

const sectionTitle = (key: string): string =>
  key.replace(/([A-Z])/g, ' $1').replace(/^./, (s) => s.toUpperCase()).trim();

export const BrsrGapClosurePanel: React.FC<{ period?: string }> = ({ period = 'annual' }) => {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [checklist, setChecklist] = useState<GapChecklist | null>(null);

  const loadChecklist = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await ApiService.getBrsrGapClosureChecklist({ period });
      setChecklist((res?.data?.checklist as GapChecklist) || null);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Unable to load BRSR gap closure checklist');
    } finally {
      setLoading(false);
    }
  }, [period]);

  useEffect(() => {
    void loadChecklist();
  }, [loadChecklist]);

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
        <CircularProgress size={28} />
      </Box>
    );
  }

  if (error) {
    return <Alert severity="error">{error}</Alert>;
  }

  if (!checklist) {
    return <Alert severity="info">No BRSR gap-closure checklist available yet.</Alert>;
  }

  const sections = Object.entries(checklist.sections || {});

  return (
    <Stack spacing={2}>
      {checklist.scopeNote ? <Alert severity="info">{checklist.scopeNote}</Alert> : null}
      <Card variant="outlined">
        <CardContent>
          <Typography variant="subtitle2" color="text.secondary" gutterBottom>
            BRSR Principle 6 + S/G readiness
          </Typography>
          <Stack direction="row" alignItems="center" spacing={2}>
            <Typography variant="h4">{checklist.overallReadinessScore ?? 0}%</Typography>
            <Box sx={{ flex: 1 }}>
              <LinearProgress
                variant="determinate"
                value={Math.min(100, checklist.overallReadinessScore ?? 0)}
                sx={{ height: 8, borderRadius: 1 }}
              />
            </Box>
          </Stack>
        </CardContent>
      </Card>

      {(checklist.fullComplianceBlockers || []).map((blocker) => (
        <Alert key={blocker} severity="warning">{blocker}</Alert>
      ))}

      {sections.map(([key, section]) => (
        <Card key={key} variant="outlined">
          <CardContent>
            <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ mb: 1 }}>
              <Typography variant="subtitle1">{sectionTitle(key)}</Typography>
              <Chip size="small" label={`${section.readinessScore ?? 0}%`} color="primary" variant="outlined" />
            </Stack>
            <List dense disablePadding>
              {(section.items || []).map((item) => (
                <ListItem key={item.id || item.title} disableGutters>
                  <ListItemText
                    primary={(
                      <Stack direction="row" spacing={1} alignItems="center">
                        <Chip
                          size="small"
                          label={item.status === 'complete' ? 'Complete' : 'Open'}
                          color={item.status === 'complete' ? 'success' : 'warning'}
                          variant="outlined"
                        />
                        <Typography variant="body2">{item.title}</Typography>
                      </Stack>
                    )}
                    secondary={item.description}
                  />
                </ListItem>
              ))}
            </List>
          </CardContent>
        </Card>
      ))}

      {(checklist.priorityActions || []).length > 0 && (
        <Card variant="outlined">
          <CardContent>
            <Typography variant="subtitle1" gutterBottom>Priority actions</Typography>
            <List dense>
              {checklist.priorityActions!.map((action, index) => (
                <ListItem
                  key={action.gapId || action.action || index}
                  disableGutters
                  secondaryAction={(
                    <Button
                      size="small"
                      component={RouterLink}
                      to={action.hubLink || '/reporting?tab=brsr'}
                      endIcon={<ArrowForwardIcon />}
                    >
                      {action.actionLabel || 'Close gap'}
                    </Button>
                  )}
                >
                  <ListItemText
                    primary={action.action}
                    secondary={action.detail}
                  />
                </ListItem>
              ))}
            </List>
          </CardContent>
        </Card>
      )}
    </Stack>
  );
};

export default BrsrGapClosurePanel;
